<template>
  <div class="video-style-transfer">
    <!-- 顶部导航栏 -->
    <div class="page-header">
      <h1 class="page-title">{{ t('changeVideoStyle') }}</h1>
    </div>

    <!-- 主内容区域 -->
    <div class="page-content">
      <!-- 视频上传区域 -->
      <div class="upload-section">
        <div class="upload-container">
          <div class="video-preview-area">
            <MobileVideoUploader
              ref="videoUploaderRef"
              :video-url="uploadedVideoUrl"
              :max-size="50 * 1024 * 1024"
              accept="video/mp4,video/avi,video/mov,video/wmv,video/flv,video/webm"
              @onUploadSuccess="handleVideoUploadSuccess"
              @onUploadRemove="handleVideoUploadRemove"
            />
          </div>
        </div>
      </div>

      <!-- 风格选择区域 -->
      <div class="style-selection-section">
        <div class="style-label">{{ t('selectVideoStyle') }}</div>
        <div class="style-grid">
          <div 
            v-for="style in styleOptions"
            :key="style.value"
            class="style-button"
            :class="{ 'style-button--selected': selectedStyle === style.value }"
            @click="selectStyle(style.value)"
          >
            <span class="style-text">{{ t(style.label) }}</span>
          </div>
        </div>
      </div>

      <!-- 错误提示 -->
      <div v-if="formError" class="form-error-section">
        <div class="form-error">{{ formError }}</div>
      </div>
    </div>

    <!-- 底部按钮占位区域 -->
    <div class="empty-quality-selector-area" :style="{ height: '80px' }"></div>

    <!-- 底部操作按钮区域 -->
    <div class="quality-selector-area">
      <div class="generate-button-wrapper">
        <div class="generate-button-container">
          <button
            class="generate-button"
            :class="{ 'generate-button--disabled': isButtonDisabled }"
            :disabled="isButtonDisabled"
            @click="handleGenerate"
          >
            <MobileLImg v-show="isGenerating" class="loading-icon" :src="'/static/mobile_images/msg-think-loading.png'" w="16px" h="16px"></MobileLImg>
            {{ isGenerating ? t('generating') : t('generateVideo') }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileVideoUploader from '@/mobile/components/mobile-video-uploader.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import { styleOptions } from '@/types/panel-options';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { VIDEO_OPERATIONS } from '@/types/media-tool';

// 变量区域
const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 当前模块的 key
const MODULE_KEY = VIDEO_OPERATIONS.VIDEO_STYLE;

// 响应式变量
const videoUploaderRef = ref(null);
const selectedStyle = ref('');
const uploadedVideoUrl = ref('');
const uploadedVideoInfo = ref(null);
const isGenerating = ref(false);
const formError = ref('');

// 计算属性区域
const isButtonDisabled = computed(() => {
  return !uploadedVideoUrl.value || !selectedStyle.value || isGenerating.value;
});

// 点击事件区域
const selectStyle = (styleValue) => {
  selectedStyle.value = styleValue;
  formError.value = '';
};

const handleGenerate = async () => {
  // 验证表单
  if (!uploadedVideoUrl.value) {
    formError.value = t('pleaseUploadVideo');
    return;
  }
  
  if (!selectedStyle.value) {
    formError.value = t('pleaseSelectStyle');
    return;
  }

  try {
    isGenerating.value = true;
    formError.value = '';

    // 模拟生成过程
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    console.log('Generating video with style:', {
      videoUrl: uploadedVideoUrl.value,
      videoInfo: uploadedVideoInfo.value,
      style: selectedStyle.value
    });

    // 这里会调用实际的API
    // const result = await generateVideoWithStyle({
    //   videoUrl: uploadedVideoUrl.value,
    //   style: selectedStyle.value
    // });

  } catch (error) {
    console.error('Video generation failed:', error);
    formError.value = t('generationFailed');
  } finally {
    isGenerating.value = false;
  }
};

// 自定义事件区域
const handleVideoUploadSuccess = (result) => {
  console.log('Video upload success:', result);
  uploadedVideoUrl.value = result.url;
  uploadedVideoInfo.value = result;
  formError.value = '';
};

const handleVideoUploadRemove = () => {
  console.log('Video upload removed');
  uploadedVideoUrl.value = '';
  uploadedVideoInfo.value = null;
  formError.value = '';
};

// 业务逻辑区域
// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    // 设置默认视频URL和相关信息
    uploadedVideoUrl.value = result?.videoUrl ? result.videoUrl : uploadedVideoUrl.value;
    uploadedVideoInfo.value = result?.videoInfo ? result.videoInfo : uploadedVideoInfo.value;
    selectedStyle.value = result?.selectedStyle ? result.selectedStyle : selectedStyle.value;

    // 清除生成结果，避免重复使用
    mediaStore.clearGenerationResult(MODULE_KEY);
  }
};

// 周期函数区域
onMounted(() => {
  // 检测Pinia中是否有生成的视频数据
  loadGenerationResult();
});
</script>

